/* @socom-skeleton body Open__9CBufferIOFPCcUi */
unsigned char CBufferIO::Open(const char *buf, unsigned int)
{
	bool success = CFileIO::Open(buf);
	bool isOpen = CFileIO::IsOpen();

	if (isOpen)
	{
		LoadBuffer();
	}

	if (!success)
	{
		Close();
	}

	return success;
}

/* @socom-skeleton body LoadBuffer__9CBufferIOFv */
bool CBufferIO::LoadBuffer()
{
	bool success = false;

	if (CFileIO::IsOpen())
	{
		size_t size = CBufferIO::GetSize();

		if (size > 0)
		{
			if (m_bufsize < size)
			{
				m_buffer = zrealloc(m_buffer, size);
				m_bufsize = size;
			}

			m_filesize = size;

			if (m_buffer)
			{
				size = m_filesize;
				u32 position = CFileIO::fread(m_buffer, size);

				if (size == position)
				{
					m_file = (s64)m_buffer;
					success = m_buffer != NULL;
				}
				else
				{
					success = false;
					zfree(m_buffer);
					m_file = NULL;
					m_bufsize = 0;
					m_filesize = 0;
				}
			}
		}
	}

	return success;
}

/* @socom-skeleton body Close__9CBufferIOFv */
void CBufferIO::Close()
{
	if (m_buffer != NULL)
	{
		free(m_buffer);
	}

	m_file = NULL;
	m_bufsize = 0;
	m_buffer = NULL;
	m_filesize = 0;
	CFileIO::Close();
}

